    nonzero = [c for row in grid for c in row if c != 0]
    nonzero_counts = {}
    for v in nonzero:
        nonzero_counts[v] = nonzero_counts.get(v, 0) + 1
    most_common = max(nonzero_counts, key=nonzero_counts.get) if nonzero_counts else 3

    filled = []
    for row in grid:
        pat = [c for c in row if c != 0]
        if pat:
            new_row = list(row)
            for i, c in enumerate(new_row):
                if c == 0:
                    new_row[i] = pat[i % len(pat)]
            filled.append(new_row)
        else:
            filled.append([most_common] * len(row))

    result = []
    for i in range(len(filled) * 2):
        row_idx = i // 2
        row2 = []
        for j in range(len(filled[row_idx]) * 2):
            row2.append(filled[row_idx][j // 2])
        result.append(row2)
    return result
